changeSet.sql:
ALTER TABLE wf.workflow_task ALTER COLUMN assignment_kind VARCHAR(5) NOT NULL;
ALTER TABLE wf.workflow_task ALTER COLUMN assignment_ref NVARCHAR(200) COLLATE Latin1_General_100_BIN2 NOT NULL;
ALTER TABLE wf.workflow_task WITH CHECK ADD CONSTRAINT ck_workflow_task_assignment
    CHECK (assignment_kind IN ('USER', 'GROUP', 'ROLE') AND DATALENGTH(assignment_ref) BETWEEN 2 AND 400);
DROP INDEX ix_workflow_task_open_assignee ON wf.workflow_task;
ALTER TABLE wf.workflow_task DROP COLUMN assigned_user_ref;
CREATE NONCLUSTERED INDEX ix_workflow_task_open_assignment
    ON wf.workflow_task (assignment_kind, assignment_ref, id) INCLUDE (activity_id) WHERE status = 'OPEN';
CREATE NONCLUSTERED INDEX ix_workflow_task_open_scan
    ON wf.workflow_task (id) INCLUDE (assignment_kind, assignment_ref, activity_id) WHERE status = 'OPEN';
